import{_ as e,o as i,c as a,ag as t}from"./chunks/framework.B3ODPNcg.js";const d=JSON.parse('{"title":"12.3 Accessibilité","description":"","frontmatter":{},"headers":[],"relativePath":"bonnes-pratiques/accessibilite.md","filePath":"bonnes-pratiques/accessibilite.md"}'),l={name:"bonnes-pratiques/accessibilite.md"};function r(n,s,o,p,u,h){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="_12-3-accessibilite" tabindex="-1">12.3 Accessibilité <a class="header-anchor" href="#_12-3-accessibilite" aria-label="Permalink to &quot;12.3 Accessibilité&quot;">​</a></h1><p>L’accessibilité web vise à rendre les sites utilisables par tous, y compris les personnes en situation de handicap (visuel, moteur, cognitif, etc.). Un site accessible améliore l’expérience de tous les utilisateurs et respecte la législation en vigueur dans de nombreux pays.</p><h2 id="attributs-alt-pour-les-images" tabindex="-1">Attributs <code>alt</code> pour les images <a class="header-anchor" href="#attributs-alt-pour-les-images" aria-label="Permalink to &quot;Attributs `alt` pour les images&quot;">​</a></h2><p>Chaque image doit posséder un attribut <code>alt</code> qui décrit son contenu ou sa fonction. Cela permet aux lecteurs d’écran de transmettre l’information à l’utilisateur.</p><p><strong>Exemple :</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;logo.png&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Logo de l’école HELHa&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>Astuce :</strong> Si l’image est purement décorative, utilisez <code>alt=&quot;&quot;</code> pour qu’elle soit ignorée par les technologies d’assistance.</p><h2 id="labels-explicites-pour-les-formulaires" tabindex="-1">Labels explicites pour les formulaires <a class="header-anchor" href="#labels-explicites-pour-les-formulaires" aria-label="Permalink to &quot;Labels explicites pour les formulaires&quot;">​</a></h2><p>Associer chaque champ de formulaire à un label améliore la compréhension et la navigation, notamment pour les utilisateurs de lecteurs d’écran.</p><p><strong>Exemple :</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">label</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Adresse e-mail :&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">input</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>Astuce :</strong> Cliquer sur le label place automatiquement le focus sur le champ associé.</p><h2 id="navigation-au-clavier" tabindex="-1">Navigation au clavier <a class="header-anchor" href="#navigation-au-clavier" aria-label="Permalink to &quot;Navigation au clavier&quot;">​</a></h2><p>Un site accessible doit pouvoir être parcouru entièrement au clavier (tabulation, touches fléchées, etc.). Le focus doit être visible pour savoir où l’on se trouve dans la page.</p><p><strong>Astuce :</strong> Utilisez la pseudo-classe CSS <code>:focus</code> pour personnaliser l’apparence du focus.</p><h2 id="contrastes-de-couleurs" tabindex="-1">Contrastes de couleurs <a class="header-anchor" href="#contrastes-de-couleurs" aria-label="Permalink to &quot;Contrastes de couleurs&quot;">​</a></h2><p>Assurez-vous que le texte et les éléments importants sont suffisamment contrastés par rapport à leur arrière-plan. Cela facilite la lecture pour tous, notamment pour les personnes malvoyantes ou daltoniennes.</p><p><strong>Astuce :</strong> Des outils en ligne comme WebAIM Contrast Checker permettent de vérifier rapidement le contraste de vos couleurs.</p><h2 id="titres-hierarchiques" tabindex="-1">Titres hiérarchiques <a class="header-anchor" href="#titres-hierarchiques" aria-label="Permalink to &quot;Titres hiérarchiques&quot;">​</a></h2><p>Structurez votre contenu avec des titres (<code>&lt;h1&gt;</code>, <code>&lt;h2&gt;</code>, etc.) dans l’ordre logique. Cela aide à la navigation, notamment pour les utilisateurs de lecteurs d’écran qui peuvent parcourir la page par titres.</p><p><strong>Astuce :</strong> N’utilisez qu’un seul <code>&lt;h1&gt;</code> par page et respectez la hiérarchie (pas de saut de niveau).</p>',21)])])}const k=e(l,[["render",r]]);export{d as __pageData,k as default};
